<?php
namespace App\Services; use App\Models\{Account,AccountMembership,AccountMembershipBranch,User}; use Illuminate\Support\Facades\{DB,Hash};
class ProvisionMember { public function __construct(private GovernanceAudit $audit){} public function execute(User $actor,Account $account,array $data):AccountMembership { return DB::transaction(function()use($actor,$account,$data){ $email=strtolower(trim($data['email'])); $username=strtolower(trim($data['username'])); $user=User::where('email',$email)->orWhere('username',$username)->first(); if(!$user){$user=User::create(['name'=>trim($data['name']),'email'=>$email,'username'=>$username,'password'=>Hash::make($data['password']),'status'=>'active']);} $m=AccountMembership::updateOrCreate(['account_id'=>$account->id,'user_id'=>$user->id],['role'=>$data['role'],'status'=>'active','accepted_at'=>now()]); $ids=array_values(array_unique($data['branch_ids']??[])); AccountMembershipBranch::where('membership_id',$m->id)->update(['is_active'=>false]); foreach($ids as $id) AccountMembershipBranch::updateOrCreate(['membership_id'=>$m->id,'branch_id'=>$id],['account_id'=>$account->id,'is_active'=>true]); $this->audit->record($actor,'member.provisioned','account_membership',$m->id,$account->id,['role'=>$m->role]); return $m->load('user','branchAssignments'); }); } }
